"SELECT DISTINCT\r\nSPI.[PROV_ID]                                   AS PROV_ID,\r\nSPI.[Submitting Provider Name] \t\t\t\t    AS \"Servicing Provider Name\",\r\nSPI.[Submitting Provider Type]\t\t            AS \"Servicing Provider Type\",\r\nSPI.[Submitting Provider NPI]\t\t\t        AS \"Servicing Provider NPI\",\r\nSPI.[Submitting Provider State License ID]\t\tAS \"Servicing Provider State License ID\",\r\nSPI.[Submitting Provider Medicaid ID]\t\t\tAS \"Servicing Provider Medicaid ID\",\r\n--SPI.[Submitting Provider Tax ID SSN]            AS \"Servicing Provider Tax ID SSN\",\r\nSPI.[Submitting Provider Network Access Vendor] AS \"Servicing Provider Network Access Vendor\"\r\nFROM [Submitting Provider Information] AS SPI\r\n"
